import { Platform } from 'react-native';

function getHost() {
	if (Platform.OS === 'web') {
		// use the current hostname (works when running expo web)
		// when serving from a different port, ensure backend uses port 3000 or adjust accordingly
		// eslint-disable-next-line @typescript-eslint/no-explicit-any
		const win: any = typeof window !== 'undefined' ? window : undefined;
		return (win && win.location && win.location.hostname) || 'localhost';
	}

	// Android emulator uses 10.0.2.2 to reach host machine
	if (Platform.OS === 'android') {
		return '10.0.2.2';
	}

	// iOS simulator and other native platforms can reach host at localhost
	return 'localhost';
}

export const API_BASE_URL = `http://${getHost()}:3000`;
